const SIZES = [180, 120, 60, 40] as const

/**
 * /dev/icons — preview of the "unwind PUZZLES" wordmark app icon
 * (public/icons/variants/wordmark-*.png, generated by
 * scripts/generate-icons.py from the source masks in /brand) at the sizes
 * that matter, on both a light and a dark surface, plus the maskable
 * variant shown inside Android's circular safe-zone crop.
 */
export function IconsPreview() {
  return (
    <div className="mx-auto max-w-3xl px-6 py-10">
      <h1 className="mb-2 text-2xl font-black">App icon preview</h1>
      <p className="mb-8 text-[var(--color-text-secondary)]">
        "unwind" should read clearly at 40px; both "unwind" and "PUZZLES" should read at 60px.
      </p>

      <div className="grid grid-cols-2 gap-8">
        <Surface label="On light" background="#F3F7FF" labelColor="#04073A" />
        {/* Deliberately not the icon's own navy bg — that would make the
            square icon invisible against a matching panel. */}
        <Surface label="On dark" background="#1A1A2E" labelColor="#C7CBE0" />
      </div>

      <h2 className="mb-4 mt-10 font-bold">Maskable (Android safe-zone crop)</h2>
      <div className="flex items-center gap-10">
        <MaskableSample />
        <p className="max-w-sm text-sm text-[var(--color-text-secondary)]">
          The wordmark is scaled down further (68% width instead of 86%) so nothing gets clipped
          when Android crops the icon into a circle, squircle, or other shape.
        </p>
      </div>
    </div>
  )
}

function Surface({
  label,
  background,
  labelColor,
}: {
  label: string
  background: string
  labelColor: string
}) {
  return (
    <div>
      <h2 className="mb-4 font-bold">{label}</h2>
      <div className="flex flex-col items-center gap-6 rounded-2xl p-6" style={{ background }}>
        {SIZES.map((s) => (
          <IconSample key={s} src={`/icons/variants/wordmark-${s}.png`} size={s} labelColor={labelColor} />
        ))}
      </div>
    </div>
  )
}

function IconSample({ src, size, labelColor }: { src: string; size: number; labelColor: string }) {
  return (
    <div className="flex flex-col items-center gap-1.5">
      <img
        src={src}
        width={size}
        height={size}
        alt=""
        className="rounded-2xl shadow-[0_6px_14px_rgb(0_0_0_/_25%)]"
      />
      <span className="text-xs" style={{ color: labelColor }}>
        {size}px
      </span>
    </div>
  )
}

function MaskableSample() {
  return (
    <div className="flex flex-col items-center gap-1.5">
      <div
        className="h-[180px] w-[180px] overflow-hidden rounded-full shadow-[0_6px_14px_rgb(0_0_0_/_25%)]"
        style={{
          backgroundImage: 'url(/icons/variants/wordmark-maskable-180.png)',
          backgroundSize: 'cover',
        }}
      />
      <span className="text-xs text-[var(--color-text-secondary)]">180px, circle mask</span>
    </div>
  )
}
